import { FC } from 'react';

type IconName = 'close' | 'close-circle' | 'close-circle-fill' | 'check' | 'check-circle' | 'check-circle-fill' | 'arrow-left' | 'arrow-right' | 'arrow-up' | 'arrow-down' | 'chevron-up' | 'chevron-down' | 'loading' | 'search' | 'plus' | 'minus' | 'info-circle' | 'warning-circle' | 'success-circle' | 'clock';
interface IconProps {
    /** 图标名称 */
    name: IconName | string;
    /** 图标尺寸 (rpx) */
    size?: number;
    /** 图标颜色 */
    color?: string;
    /** 渲染模式 */
    renderMode?: 'auto' | 'svg' | 'image';
    /** 点击事件 */
    onClick?: () => void;
    /** 自定义类名 */
    className?: string;
}

declare const Icon: FC<IconProps>;

export { Icon, Icon as default };
export type { IconName, IconProps };
